"""One field-contract shape, three vendors who publish theirs three different ways.

The console's forms are DATA everywhere (`platform_actions`), but "the documented contract" comes
from a different artefact per custodian, and none of them is an OpenAPI spec:

  * **Morgan Lloyd** -- HTML field tables on a Slate page, parsed into `morgan_lloyd.manifest`;
  * **Seccl** -- JSON Schemas in `pkgs/seccl`, themselves generated by merging the 205 example
    bodies in the vendored Postman collection (Seccl publishes no schema at all);
  * **SEI** -- sample request bodies in the API sheet they issue per firm, flattened into
    `sei.manifest`.

So this module is the adapter: each resolver returns the SAME `Contract`, and everything
downstream -- the drawer, `validate`, the typed payload -- reads one shape. Without it,
`platform_actions` would grow a branch per vendor in five places and the rules that matter (an
unknown field is refused, a missing required one is named) would drift apart per provider.

NOTHING HERE INVENTS A FIELD. A vendor who does not document one gets an empty contract and the
caller says so, which is a visible gap rather than a form that looks authoritative and is guessed.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from functools import cache
from typing import Any

__all__ = ["Contract", "ContractField", "Option", "resolve_contract"]


@dataclass(frozen=True, slots=True)
class Option:
    label: str | None
    value: int


@dataclass(frozen=True, slots=True)
class ContractField:
    """One documented field. Structurally what `morgan_lloyd.manifest.Field` already is, so the
    ML resolver can hand its own objects straight back and no adapter runs for the vendor whose
    documentation is richest."""

    name: str
    type: str
    required: bool
    description: str = ""
    options: tuple[Option, ...] = ()
    multiselect: bool = False
    required_note: str = ""

    @property
    def conditional(self) -> bool:
        return "*" in self.required_note


@dataclass(frozen=True, slots=True)
class Contract:
    """What one action accepts."""

    fields: tuple[Any, ...] = ()
    parameters: tuple[Any, ...] = ()
    lookups: tuple[dict[str, str], ...] = ()
    nested: tuple[str, ...] = field(default_factory=tuple)
    """Names of documented sub-objects a FLAT form cannot express.

    Reported rather than dropped: an action whose body nests (`addressDetail`, or SEI's
    `clientList[].newClient.individualDetails`) is not one a generated drawer can build, and
    saying which parts are missing is the difference between "this form is incomplete" and a
    form that silently omits half the payload.
    """

    def field(self, name: str) -> Any | None:
        return next((f for f in self.fields if f.name == name), None)

    @property
    def required_fields(self) -> tuple[Any, ...]:
        return tuple(f for f in self.fields if f.required)


# --- Seccl -------------------------------------------------------------------------------------
#
# `pkgs/seccl/src/seccl/schemas/{resource}.json` carries `$defs.{Resource}Create` and
# `{Resource}Update`. Those schemas are INFERRED FROM EXAMPLES -- required means "present in every
# example Seccl published", not "the API rejects it otherwise" -- so a required field here is a
# strong hint and not a promise, which is why `services/seccl`'s live-checked models stay
# authoritative wherever the two disagree (pkgs/seccl/README.md).

_SCALARS = {"string", "integer", "number", "boolean"}


@cache
def _seccl_schema(resource: str) -> dict[str, Any]:
    from importlib import resources as importlib_resources

    text = (
        importlib_resources.files("seccl")
        .joinpath("schemas", f"{resource}.json")
        .read_text("utf-8")
    )
    return dict(json.loads(text))


def _seccl_type(spec: dict[str, Any]) -> str | None:
    """The scalar type of a property, or None when it is a nested object or a list of them.

    `anyOf` is how the generator spells "nullable": `[{"type": "string"}, {"type": "null"}]`.
    Taking the first non-null member is the shape, not a guess.
    """
    if "$ref" in spec:
        return None
    kinds = spec.get("anyOf") or [spec]
    for kind in kinds:
        if "$ref" in kind:
            return None
        found = kind.get("type")
        if found == "null":
            continue
        if found in _SCALARS:
            return {"integer": "int", "number": "decimal", "boolean": "bool"}.get(found, "string")
        if found == "array":
            return None
    return None


def seccl_contract(resource: str, shape: str) -> Contract | None:
    """`resource` is the schema file (`client`), `shape` the definition (`ClientCreate`)."""
    try:
        schema = _seccl_schema(resource)
    except (FileNotFoundError, ModuleNotFoundError):
        return None
    defined = (schema.get("$defs") or {}).get(shape)
    if not isinstance(defined, dict):
        return None
    required = set(defined.get("required") or [])
    fields: list[ContractField] = []
    nested: list[str] = []
    for name, spec in (defined.get("properties") or {}).items():
        kind = _seccl_type(spec if isinstance(spec, dict) else {})
        if kind is None:
            # A nested object or an array of them. Named, not silently dropped.
            nested.append(name)
            continue
        fields.append(
            ContractField(
                name=name,
                type=kind,
                required=name in required,
                description=str((spec or {}).get("description") or ""),
            )
        )
    return Contract(fields=tuple(fields), nested=tuple(nested))


# --- the dispatch --------------------------------------------------------------------------------


def resolve_contract(provider: str, reference: str, method: str = "") -> Contract | None:
    """The documented contract for one action, whatever the vendor publishes it as.

    `reference` is the provider's own way of naming an operation: a Dataverse action for Morgan
    Lloyd, `resource:Shape` for Seccl, a service path for SEI.
    """
    if provider == "morgan-lloyd":
        from morgan_lloyd.manifest import operation

        found = operation(reference, method or None)
        if found is None:
            return None
        # Handed back as-is: `manifest.Field` already has this shape, and copying it would be a
        # second place for the option sets and the `No*` notes to lose something.
        return Contract(
            fields=found.fields,
            parameters=found.parameters,
            lookups=found.lookups,
        )
    if provider == "seccl":
        resource, _, shape = reference.partition(":")
        return seccl_contract(resource, shape) if shape else None
    if provider == "sei":
        return sei_contract(reference)
    return None


# --- SEI --------------------------------------------------------------------------------------
#
# Fields are DOTTED PATHS into a JSON:API-ish envelope (`data.attributes.accountStatus`). The form
# collects leaves; `platform_actions` rebuilds the envelope from the paths, which is mechanical and
# needs no per-service mapping table.


def sei_contract(path: str) -> Contract | None:
    try:
        from sei.manifest import service
    except ImportError:  # pragma: no cover - only when the package is missing
        return None
    found = service(path)
    if found is None:
        return None
    return Contract(
        fields=tuple(
            ContractField(
                name=f.name,
                type=f.type,
                # NOTHING IS REQUIRED. The sheet has no Required column, so requiredness is
                # unknown -- and an unknown asserted as `True` blocks legitimate partial calls
                # while an unknown asserted as `False` merely lets the vendor answer. The second
                # failure is recoverable and names itself; the first is not.
                required=False,
                description=f.description,
            )
            for f in found.fields
        ),
        nested=found.repeating,
    )
